void drawLopakaImage(int x, int y, const uint16_t *image, int w, int h) {
    // Tạo bộ đệm 1 dòng để tăng tốc độ vẽ (Tối ưu cho Adafruit)
    uint16_t rowBuffer[w]; 
    
    for (int j = 0; j < h; j++) {
        for (int i = 0; i < w; i++) {
            // Đọc màu gốc bị sai
            uint16_t color = pgm_read_word(&image[j * w + i]);
            // Thực hiện phép thuật đảo chiều Byte (Swap Endian)
            rowBuffer[i] = (color >> 8) | (color << 8); 
        }
        // In nguyên một dòng ra màn hình cực nhanh
        tft.drawRGBBitmap(x, y + j, rowBuffer, w, 1); 
    }
}

// ===================================================================
// 1. HÀM VẼ GIAO DIỆN TĨNH (Đã được chuẩn hóa sang Adafruit GFX)
// ===================================================================
void drawStaticUI() {
    tft.fillScreen(0x0000); // Nền đen
    
    // Ảnh nền (Nên chú ý bộ nhớ RAM nếu ảnh này full màn hình)
    drawLopakaImage(0, 1, image_Thi_t_k__ch_a_c__t_n__3__pixels, 320, 240);
    
    // Các đường gạch ngang
    tft.drawLine(0, 80, 320, 80, 0x05FA);
    tft.drawLine(0, 160, 320, 160, 0x05FA);

    // --- VẼ CHỮ TIÊU ĐỀ ---
    tft.setFont(&FreeMonoBold9pt7b);
    
    // Lưu ý: Font Adafruit vẽ chữ từ DƯỚI ĐÁY lên, 
    // nên mình đã cộng thêm 13px vào trục Y cho bạn để chữ không bị lẹm lên trên
    tft.setTextColor(0x05FA);
    tft.setCursor(11, 28);   tft.print("Temp");
    tft.setCursor(91, 28);   tft.print("Humi");
    
    tft.setTextColor(0x055E);
    tft.setCursor(168, 28);  tft.print("Press");
    
    tft.setTextColor(0x05FA);
    tft.setCursor(11, 100);  tft.print("Lat");
    tft.setCursor(145, 98);  tft.print("Lon");
    tft.setCursor(9, 180);   tft.print("Speed");
    tft.setCursor(97, 181);  tft.print("RPM");
    tft.setCursor(156, 179); tft.print("Energy");

    // --- VẼ ẢNH VÀ ICON TRANG TRÍ ---
    // (Dùng fillRoundRect bo góc để tạo hình Oval/Ellipse hoàn hảo)
    tft.fillRoundRect(266, 95, 54, 40, 20, 0xFFFF);
    drawLopakaImage(279, 100, image_images_pixels, 30, 30);

    tft.fillRoundRect(266, 18, 54, 40, 20, 0xFFFF);
    drawLopakaImage(275, 22, image_design_humidity_icon_style_free_vector_pixels, 37, 30);

    tft.fillRoundRect(265, 172, 54, 40, 20, 0xFFFF);
    drawLopakaImage(278, 176, image_images_1_pixels, 30, 30);
}

// ===================================================================
// 2. TASK CẬP NHẬT SỐ LIỆU ĐỘNG VÀ ĐA NHIỆM SPI
// ===================================================================

// Hàm "chữa cháy" cho Adafruit: Tự động xóa khung chữ cũ trước khi in chữ mới
void printDynamicValue(int x, int y, int w, int h, String value, uint16_t color) {
    tft.fillRect(x, y - h + 5, w, h, 0x0000); // Dùng cọ đen xóa vùng cũ
    tft.setTextColor(color);
    tft.setCursor(x, y);
    tft.print(value);
}

void ScreenTFT_Task(void *parameter) {
    SerialPrintlnSafe("[TFT] Task Started - Lopaka UI");

    GPSData_t currentGPS = {};
    BMEData_t currentBME = {};
    CANData_t currentCAN = {};

    String strLat, strLon, strTemp, strHum, strPress, strRPM, strSpeed, strEnergy;

    for (;;) {
        // Hứng dữ liệu từ các hộp thư
        if (xGPSMailbox != NULL) xQueuePeek(xGPSMailbox, &currentGPS, 0);
        if (xBMEMailbox != NULL) xQueuePeek(xBMEMailbox, &currentBME, 0);
        if (xCANMailbox != NULL) xQueuePeek(xCANMailbox, &currentCAN, 0);

        // Đóng gói thành chuỗi trước để giảm thiểu thời gian chiếm giữ SPI
        strTemp  = String(currentBME.temperature, 1);
        strHum   = String(currentBME.humidity, 1);
        strPress = String(currentBME.pressure, 0);
        strLat   = String(currentGPS.currentLat, 4);
        strLon   = String(currentGPS.currentLon, 4);
        strSpeed = String(currentCAN.vehicleSpeed, 0);
        strRPM   = String(currentCAN.engineRPM, 0);
        
        // --- ĐỒNG BỘ NĂNG LƯỢNG (Đọc từ biến batteryVoltage đã nhận qua CAN) ---
        if (currentCAN.batteryVoltage < 1.0) {
            strEnergy = "0.0V"; // Trường hợp chưa có pin hoặc lỗi dây
        } else {
            strEnergy = String(currentCAN.batteryVoltage, 1) + "V"; // Lấy 1 số thập phân (Ví dụ: 14.8V)
        }

        // Tự động tính toán màu sắc cảnh báo Pin yếu
        uint16_t energyColor = 0x07E0; // Màu XANH LÁ (ILI9341_GREEN) mặc định

        if (currentCAN.batteryVoltage < 1.0) {
            // Trường hợp chưa có pin hoặc đứt dây
            strEnergy = "0%"; 
            energyColor = 0xF800; // Màu ĐỎ (ILI9341_RED) cảnh báo
        } else {
            // Chuyển đổi Volt sang millivolt
            long volInMilli = (long)(currentCAN.batteryVoltage * 1000); 
            
            // Map giá trị theo chuẩn pin của bạn (12.8V -> 0%, 16.8V -> 100%)
            int percent = map(volInMilli, 12800, 16800, 0, 100);
            
            // Ép % nằm gọn trong khoảng 0 - 100
            percent = constrain(percent, 0, 100);
            
            // Nối thêm dấu % để in ra màn hình
            strEnergy = String(percent) + "%";

            // Tự động tính toán màu sắc cảnh báo Pin yếu (Ví dụ: Dưới 20% là pin yếu)
            if (percent <= 20) {
                energyColor = 0xF800; // Đổi sang màu ĐỎ
            }
        }

        // Khóa luồng SPI, đẩy lên màn hình
        if (xSemaphoreTake(xSPIMutex, pdMS_TO_TICKS(50)) == pdTRUE) {
            
            tft.setFont(&FreeMonoBold12pt7b); // Sử dụng font to cho giá trị

            // Vị trí trục Y đã được cộng bù 16px so với Lopaka để font vẽ không bị lẹm 
            printDynamicValue(17, 60, 60, 20, strTemp, 0xFFFF);
            printDynamicValue(97, 58, 60, 20, strHum, 0xFFFF);
            printDynamicValue(181, 58, 60, 20, strPress, 0xFFFF);
            
            printDynamicValue(11, 129, 110, 20, strLat, 0xFFFF);
            printDynamicValue(147, 130, 110, 20, strLon, 0xFFFF);
            
            printDynamicValue(18, 211, 60, 20, strSpeed, 0xFFFF);
            printDynamicValue(99, 211, 60, 20, strRPM, 0xFFFF);
            
            // Nếu HI thì màu đỏ, OK thì màu xanh
            printDynamicValue(179, 213, 60, 20, strEnergy, energyColor);

            xSemaphoreGive(xSPIMutex); // Trả luồng SPI cho thẻ nhớ
        }
        
        vTaskDelay(pdMS_TO_TICKS(500));
    }
}